static inline enum msstyles_platform msstyles_detect_platform_from_classes(int (*has_class)(const void *ctx, const char *name), const void *ctx)
{
    if (has_class(ctx, "DarkMode::TaskManager")) return MSSTYLES_PLATFORM_WIN11;
    if (has_class(ctx, "W8::TaskbandExtendedUI")) return MSSTYLES_PLATFORM_WIN81;
    if (has_class(ctx, "DWMTouch") || has_class(ctx, "DWMPen")) return MSSTYLES_PLATFORM_WIN10;
    if (has_class(ctx, "QueryBuilder")) return MSSTYLES_PLATFORM_VISTA;
    return MSSTYLES_PLATFORM_WIN7;
}

